const IG_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const IG_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw??2}"${o.ex?' '+o.ex:''}/>`;
const IG_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return IG_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const IG_GREY='#5C6577', IG_STEEL='#495057', IG_CU='#C2410C', IG_DARK='#343A40';
/* a vertical coil of n loops from (x,y) down, loops bulging right (d=1) or left (d=-1) */
const IG_coil=(x,y,n,h,col,d=1,w=3)=>{let p=`M${x},${y}`;for(let i=0;i<n;i++)p+=` a${10},${h/2} 0 0 ${d>0?1:0} 0,${h}`;return `<path d="${p}" fill="none" stroke="${col}" stroke-width="${w}"/>`};
/* a battery: long and short plates, horizontal, centred at x,y */
const IG_batt=(x,y,col=IG_DARK)=>IG_L(x-22,y-10,x+22,y-10,col,4)+IG_L(x-12,y,x+12,y,col,4)+IG_L(x-22,y+10,x+22,y+10,col,4)+IG_L(x-12,y+20,x+12,y+20,col,4);
/* a spark: a zigzag bolt centred at x,y */
const IG_spark=(x,y,s=1,col='#FAB005')=>`<polyline points="${x-8*s},${y-26*s} ${x+8*s},${y-6*s} ${x-6*s},${y} ${x+8*s},${y+26*s}" fill="none" stroke="${col}" stroke-width="${6*s}" stroke-linejoin="round" stroke-linecap="round"/>`;
/* a spark plug, tip down at x,y */
const IG_plug=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-10" y="-96" width="20" height="26" rx="4" fill="#DEE2E6" stroke="${IG_STEEL}" stroke-width="3"/><rect x="-16" y="-70" width="32" height="40" rx="6" fill="#FFFFFF" stroke="${IG_STEEL}" stroke-width="3"/><rect x="-20" y="-30" width="40" height="18" fill="#ADB5BD" stroke="${IG_STEEL}" stroke-width="3"/><line x1="0" y1="-12" x2="0" y2="0" stroke="${IG_DARK}" stroke-width="4"/><path d="M14,-12 L14,6 L4,6" fill="none" stroke="${IG_DARK}" stroke-width="4"/></g>`;
/* a magnet rotor: a circle split N/S, centred at x,y */
const IG_magnet=(x,y,r=40)=>`<path d="M${x-r},${y} A${r},${r} 0 0 1 ${x+r},${y} Z" fill="#E03131"/><path d="M${x-r},${y} A${r},${r} 0 0 0 ${x+r},${y} Z" fill="#4C6EF5"/><circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="${IG_DARK}" stroke-width="3"/>`+IG_T(x,y-r*.3,'N',{fs:22,fw:800,a:'middle',fill:'#FFFFFF'})+IG_T(x,y+r*.62,'S',{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});
const IG_rot=(x,y,r,col)=>`<path d="M${x+r*.7},${y-r*.7} A${r},${r} 0 0 1 ${x+r*.7},${y+r*.7}" fill="none" stroke="${col}" stroke-width="4"/>`+`<polygon points="${x+r*.7-10},${y+r*.7-2} ${x+r*.7+8},${y+r*.7+6} ${x+r*.7-2},${y+r*.7-16}" fill="${col}"/>`;
const IG_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
/* crank-angle bar picture: degrees mapped to x */
